INSERT INTO public.celestial_objects (id,name,type,parent_id,route_category,route_order,branch_order,real_distance_from_sun,distance_unit,diameter,orbital_period,temperature,description,facts,journey_index,image_url,image_source,source_url,attribution) VALUES
('sun','Sun','star',NULL,'main',0,0,0.0,'AU','1,391,400 km','230 Myr (galactic)','5,505 °C surface','The G-type main-sequence star at the centre of the Solar System and the origin point of every mission.','["Holds 99.86% of the Solar System''s mass", "Core temperature reaches ~15 million \u00b0C", "Converts 600 million tonnes of hydrogen to helium every second", "Light takes 8 minutes 20 seconds to reach Earth", "Its magnetic activity cycles roughly every 11 years", "The solar wind extends past the Kuiper Belt"]',0,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/The_Sun_in_white_light.jpg/800px-The_Sun_in_white_light.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Sun','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('mercury','Mercury','planet',NULL,'main',1,0,0.387,'AU','4,879 km','88 days','-173 to 427 °C','The smallest planet and the closest to the Sun, a cratered world of extremes.','["A solar day on Mercury lasts 176 Earth days", "It has the largest temperature swing of any planet", "Its iron core makes up about 85% of its radius", "Water ice survives in permanently shadowed polar craters", "The Caloris Basin is 1,550 km across", "It has a very thin exosphere, not a true atmosphere"]',1,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Mercury_in_true_color.jpg/800px-Mercury_in_true_color.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Mercury_(planet)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('venus','Venus','planet',NULL,'main',2,0,0.723,'AU','12,104 km','225 days','464 °C','Earth''s runaway-greenhouse twin, wrapped in crushing clouds of sulfuric acid.','["Surface pressure is 92 times Earth''s", "It rotates backwards compared to most planets", "A Venusian day is longer than its year", "Hottest planet in the Solar System despite not being closest to the Sun", "Over 1,600 major volcanoes have been mapped", "Clouds reflect 75% of incoming sunlight"]',2,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Venus_2_Approach_Image.jpg/800px-Venus_2_Approach_Image.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Venus','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('earth','Earth','planet',NULL,'main',3,0,1.0,'AU','12,742 km','365.25 days','-88 to 58 °C','The only known world with liquid surface water and life — mission control''s home port.','["71% of the surface is covered in water", "The magnetic field deflects most of the solar wind", "Plate tectonics continually recycle the crust", "The atmosphere is 78% nitrogen and 21% oxygen", "It is the densest planet in the Solar System", "Its rotation is slowing by ~1.7 ms per century"]',3,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Meteosat-12-fci-march-equinox-2025-noon.jpg/800px-Meteosat-12-fci-march-equinox-2025-noon.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Earth','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('moon','Moon','moon','earth','branch',3,1,1.0,'AU','3,475 km','27.3 days','-173 to 127 °C','Earth''s only natural satellite and the first world humans ever walked on.','["Tidally locked, so one hemisphere always faces Earth", "Drifting away from Earth at 3.8 cm per year", "Twelve humans have walked on its surface", "Its far side has a much thicker crust", "Likely formed from a giant impact 4.5 billion years ago", "Stabilises Earth''s axial tilt"]',4,'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/FullMoon2010.jpg/800px-FullMoon2010.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Moon','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('mars','Mars','planet',NULL,'main',4,0,1.524,'AU','6,779 km','687 days','-153 to 20 °C','The rusty desert world, the most explored planet beyond Earth.','["Olympus Mons is the tallest volcano in the Solar System", "Valles Marineris stretches over 4,000 km", "Its red colour comes from iron oxide dust", "Polar caps are made of water and carbon dioxide ice", "Global dust storms can last for months", "Gravity is 38% of Earth''s"]',5,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Mars_-_August_30_2021_-_Flickr_-_Kevin_M._Gill.png/800px-Mars_-_August_30_2021_-_Flickr_-_Kevin_M._Gill.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Mars','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('phobos','Phobos','moon','mars','branch',4,1,1.524,'AU','22.5 km','7.7 hours','-40 °C','The larger, doomed inner moon of Mars, spiralling towards its planet.','["Orbits Mars three times per Martian day", "Will break apart or crash within 50 million years", "Stickney crater spans nearly half its width", "Gravity is about 1/1800th of Earth''s", "Likely a captured asteroid or impact debris", "Rises in the west and sets in the east"]',6,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Phobos_colour_2008.jpg/800px-Phobos_colour_2008.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Phobos_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('deimos','Deimos','moon','mars','branch',4,2,1.524,'AU','12.4 km','30.3 hours','-40 °C','Mars'' small, smooth outer moon, barely more than a drifting rock.','["Its name means ''dread'' in Greek", "Regolith fills in most of its craters", "Escape velocity is only 5.6 m/s", "Takes 2.7 hours to cross the Martian sky", "Discovered by Asaph Hall in 1877", "Slowly drifting away from Mars"]',7,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/NASA-Deimos-MarsMoon-20090221.jpg/800px-NASA-Deimos-MarsMoon-20090221.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Deimos_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('asteroid_belt','Asteroid Belt','region',NULL,'main',5,0,2.7,'AU','~2.2–3.2 AU wide','4.6 years (mean)','-73 °C','The rocky frontier between Mars and Jupiter, holding millions of leftover planetesimals.','["Total mass is only about 4% of the Moon''s", "Over 1.3 million asteroids larger than 1 km are known", "Jupiter''s gravity prevented a planet from forming here", "Kirkwood gaps are cleared by orbital resonances", "Spacecraft cross it safely \u2014 objects are far apart", "Ceres alone holds a quarter of the belt''s mass"]',8,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Asteroid_belt_positions-en.png/800px-Asteroid_belt_positions-en.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Asteroid_belt','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('ceres','Ceres','dwarf_planet','asteroid_belt','branch',5,1,2.77,'AU','940 km','4.6 years','-105 °C','The largest object in the asteroid belt and the closest dwarf planet to the Sun.','["First asteroid ever discovered, in 1801", "Bright salt deposits shine in Occator crater", "May hold more fresh water than Earth", "Visited by NASA''s Dawn spacecraft in 2015", "Classified as both an asteroid and a dwarf planet", "Has a possible subsurface brine reservoir"]',9,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Ceres_-_RC3_-_Haulani_Crater_%2822381131691%29_%28cropped%29.jpg/800px-Ceres_-_RC3_-_Haulani_Crater_%2822381131691%29_%28cropped%29.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Ceres_(dwarf_planet)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('vesta','Vesta','asteroid','asteroid_belt','branch',5,2,2.36,'AU','525 km','3.6 years','-188 to -18 °C','The brightest asteroid visible from Earth and a surviving protoplanet.','["Occasionally visible to the naked eye", "A giant south-pole impact carved out 1% of its volume", "About 5% of meteorites on Earth come from Vesta", "Has a differentiated iron core", "Rotates once every 5.3 hours", "Studied by Dawn for 14 months"]',10,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Vesta_in_natural_color.jpg/800px-Vesta_in_natural_color.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/4_Vesta','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('jupiter','Jupiter','planet',NULL,'main',6,0,5.203,'AU','139,820 km','11.9 years','-145 °C','The Solar System''s giant, a stormy gas world with a family of 95 known moons.','["More massive than all other planets combined", "The Great Red Spot has raged for centuries", "Rotates once every 9.9 hours", "Its magnetosphere is the largest structure in the Solar System", "Has faint dust rings discovered by Voyager 1", "Shields the inner planets from many comets"]',11,'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Jupiter_OPAL_2024.png/800px-Jupiter_OPAL_2024.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Jupiter','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('io','Io','moon','jupiter','branch',6,1,5.203,'AU','3,643 km','1.77 days','-130 °C','The most volcanically active body known, squeezed by Jupiter''s tides.','["Over 400 active volcanoes", "Plumes rise up to 500 km above the surface", "Surface is repaved by sulfur compounds", "Tidal flexing heats its interior", "Feeds a plasma torus around Jupiter", "Almost no impact craters remain"]',12,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Io_highest_resolution_true_color.jpg/800px-Io_highest_resolution_true_color.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Io_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('europa','Europa','moon','jupiter','branch',6,2,5.203,'AU','3,122 km','3.55 days','-160 °C','An ice-shelled ocean world and one of the best places to search for life.','["Hides a global saltwater ocean under its ice", "Smoothest solid surface in the Solar System", "Water plumes may erupt from its south pole", "Its ocean may hold twice Earth''s water", "Crisscrossed by reddish lineae fractures", "Target of NASA''s Europa Clipper mission"]',13,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Europa_-_Perijove_45_%28cropped%29.png/800px-Europa_-_Perijove_45_%28cropped%29.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Europa_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('ganymede','Ganymede','moon','jupiter','branch',6,3,5.203,'AU','5,268 km','7.15 days','-163 °C','The largest moon in the Solar System — bigger than the planet Mercury.','["Only moon with its own magnetic field", "Larger than Mercury but only half its mass", "Has both ancient dark and younger grooved terrain", "Likely holds a subsurface ocean", "Discovered by Galileo in 1610", "ESA''s JUICE mission will orbit it"]',14,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Ganymede_-_Perijove_34_Composite.png/800px-Ganymede_-_Perijove_34_Composite.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Ganymede_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('callisto','Callisto','moon','jupiter','branch',6,4,5.203,'AU','4,821 km','16.7 days','-139 °C','The most heavily cratered object known, an ancient and quiet outer Galilean moon.','["Its surface is around 4 billion years old", "Sits outside Jupiter''s harshest radiation belts", "Valhalla crater has rings 1,900 km across", "Barely differentiated interior", "Considered a candidate for a future crewed base", "Almost no geological activity"]',15,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Callisto_VGR2_C2060635_OGB.png/800px-Callisto_VGR2_C2060635_OGB.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Callisto_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('saturn','Saturn','planet',NULL,'main',7,0,9.537,'AU','116,460 km','29.5 years','-178 °C','The ringed jewel of the Solar System, a gas giant less dense than water.','["Its rings are mostly water ice", "Would float in a sufficiently large ocean", "A hexagonal jet stream circles its north pole", "Winds reach 1,800 km/h", "Has 146 confirmed moons", "Cassini studied it for 13 years"]',16,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Saturn_global_view_from_Cassini%2C_rings_open_Better_Colour.png/800px-Saturn_global_view_from_Cassini%2C_rings_open_Better_Colour.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Saturn','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('mimas','Mimas','moon','saturn','branch',7,1,9.537,'AU','396 km','0.94 days','-200 °C','The ''Death Star'' moon, dominated by the enormous Herschel crater.','["Herschel crater is a third of its diameter", "Smallest known body rounded by its own gravity", "May hide a young internal ocean", "Shepherds the Cassini Division in the rings", "Named after a Greek Titan", "Discovered by William Herschel in 1789"]',17,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Mimas_Masked.jpg/800px-Mimas_Masked.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Mimas_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('enceladus','Enceladus','moon','saturn','branch',7,2,9.537,'AU','504 km','1.37 days','-201 °C','A tiny icy moon shooting geysers of ocean water into space.','["Plumes erupt from ''tiger stripe'' fractures", "Feeds Saturn''s E ring with ice grains", "Reflects almost all sunlight that hits it", "Its ocean contains organic molecules", "Cassini flew directly through its plumes", "A prime astrobiology target"]',18,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/PIA17202_-_Approaching_Enceladus.jpg/800px-PIA17202_-_Approaching_Enceladus.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Enceladus','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('tethys','Tethys','moon','saturn','branch',7,3,9.537,'AU','1,062 km','1.89 days','-187 °C','An almost pure water-ice moon scarred by the vast Odysseus crater.','["Density suggests it is nearly all water ice", "Ithaca Chasma runs 2,000 km across it", "Odysseus crater is 450 km wide", "Shares its orbit with two trojan moons", "Discovered by Cassini in 1684", "Extremely bright and reflective"]',19,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Global_view_of_Tethys_from_Cassini.jpg/800px-Global_view_of_Tethys_from_Cassini.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Tethys_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('dione','Dione','moon','saturn','branch',7,4,9.537,'AU','1,123 km','2.74 days','-186 °C','An icy moon streaked with bright cliffs of fractured ice.','["Its ''wispy terrain'' is actually ice cliffs", "May have a subsurface ocean", "Has a tenuous oxygen exosphere", "Locked in resonance with Enceladus", "Trailing hemisphere is heavily cratered", "Named after a Greek Titaness"]',20,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Dione_in_natural_light.jpg/800px-Dione_in_natural_light.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Dione_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('rhea','Rhea','moon','saturn','branch',7,5,9.537,'AU','1,527 km','4.52 days','-174 °C','Saturn''s second-largest moon, a cold and ancient ice world.','["Roughly three-quarters water ice by mass", "May once have had a faint ring system", "Has a thin oxygen and carbon dioxide exosphere", "Surface is saturated with craters", "Discovered in 1672 by Cassini", "No significant internal heat"]',21,'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/PIA07763_Rhea_full_globe5.jpg/800px-PIA07763_Rhea_full_globe5.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Rhea_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('titan','Titan','moon','saturn','branch',7,6,9.537,'AU','5,150 km','15.9 days','-179 °C','The only moon with a thick atmosphere and standing liquid on its surface.','["Atmosphere is denser than Earth''s", "Lakes and seas of liquid methane and ethane", "Huygens landed there in 2005", "Surface pressure is 1.45 bar", "Likely has a subsurface water ocean", "NASA''s Dragonfly will fly there in the 2030s"]',22,'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Titan_in_true_color_by_Kevin_M._Gill.jpg/800px-Titan_in_true_color_by_Kevin_M._Gill.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Titan_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('iapetus','Iapetus','moon','saturn','branch',7,7,9.537,'AU','1,469 km','79.3 days','-143 °C','The two-toned moon with a bizarre equatorial ridge.','["One hemisphere is far darker than the other", "A 20 km high ridge circles its equator", "Orbits far outside Saturn''s other big moons", "Its orbit is steeply inclined", "Discovered by Cassini in 1671", "Shaped like a walnut"]',23,'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Iapetus_trailing_natural_color.jpg/800px-Iapetus_trailing_natural_color.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Iapetus_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('phoebe','Phoebe','moon','saturn','branch',7,8,9.537,'AU','213 km','550 days','-198 °C','A captured outer moon orbiting Saturn backwards.','["Orbits Saturn in retrograde", "Probably a captured Kuiper Belt object", "Source of the huge Phoebe ring", "Very dark, carbon-rich surface", "First moon discovered photographically, in 1899", "Rotates once every 9.3 hours"]',24,'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Phoebe_cassini_full.jpg/800px-Phoebe_cassini_full.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Phoebe_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('uranus','Uranus','planet',NULL,'main',8,0,19.191,'AU','50,724 km','84 years','-224 °C','The tipped-over ice giant, coldest planet in the Solar System.','["Rotates on its side at a 98\u00b0 tilt", "Coldest planetary atmosphere recorded", "Has 13 known narrow rings", "Visited only once, by Voyager 2 in 1986", "Methane gives it a blue-green colour", "Each pole gets 42 years of sunlight"]',25,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Uranus_Voyager2_color_calibrated.png/800px-Uranus_Voyager2_color_calibrated.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Uranus','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('miranda','Miranda','moon','uranus','branch',8,1,19.191,'AU','471 km','1.41 days','-187 °C','A jumbled little moon with the tallest known cliff in the Solar System.','["Verona Rupes may be 20 km tall", "Looks assembled from mismatched pieces", "Smallest of Uranus'' five major moons", "Discovered by Gerard Kuiper in 1948", "Extreme past tidal heating is suspected", "Surface mixes very old and young terrain"]',26,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Miranda_mosaic_in_color_-_Voyager_2.png/800px-Miranda_mosaic_in_color_-_Voyager_2.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Miranda_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('ariel','Ariel','moon','uranus','branch',8,2,19.191,'AU','1,158 km','2.52 days','-213 °C','The brightest of Uranus'' moons, with young resurfaced valleys.','["Youngest surface of the Uranian moons", "Deep rift valleys cut across it", "Likely resurfaced by cryovolcanism", "Roughly half water ice by mass", "Discovered by William Lassell in 1851", "Named after a spirit in Shakespeare''s Tempest"]',27,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Ariel_in_monochrome.jpg/800px-Ariel_in_monochrome.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Ariel_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('umbriel','Umbriel','moon','uranus','branch',8,3,19.191,'AU','1,169 km','4.14 days','-198 °C','The darkest major moon of Uranus, ancient and heavily cratered.','["Reflects only about 16% of light", "The bright Wunda crater ring is a mystery", "Oldest surface among Uranus'' large moons", "Discovered in 1851 by Lassell", "Mostly ice and rock in equal parts", "Shows almost no signs of resurfacing"]',28,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/PIA00040_Umbrielx2.47.jpg/800px-PIA00040_Umbrielx2.47.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Umbriel','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('titania','Titania','moon','uranus','branch',8,4,19.191,'AU','1,578 km','8.7 days','-203 °C','The largest moon of Uranus, scarred by enormous canyon systems.','["Messina Chasma runs 1,500 km long", "Eighth-largest moon in the Solar System", "May hold a thin subsurface ocean", "Discovered by William Herschel in 1787", "Carbon dioxide ice detected on its surface", "Roughly half rock, half ice"]',29,'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Titania_VGR2_C2684315.png/800px-Titania_VGR2_C2684315.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Titania_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('oberon','Oberon','moon','uranus','branch',8,5,19.191,'AU','1,522 km','13.5 days','-203 °C','The outermost large Uranian moon, an old cratered ice world.','["Craters have dark floors of unknown material", "One mountain rises about 11 km", "Second largest moon of Uranus", "Discovered in 1787 with Titania", "Orbits partly outside Uranus'' magnetosphere", "Surface is ancient and unresurfaced"]',30,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Oberon_in_true_color_by_Kevin_M._Gill.jpg/800px-Oberon_in_true_color_by_Kevin_M._Gill.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Oberon_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('neptune','Neptune','planet',NULL,'main',9,0,30.069,'AU','49,244 km','165 years','-214 °C','The windiest world known, a distant blue ice giant.','["Winds reach 2,100 km/h", "Discovered by mathematical prediction in 1846", "Radiates 2.6 times the energy it receives", "Has completed only one orbit since discovery", "Its rings are clumped into bright arcs", "Visited once, by Voyager 2 in 1989"]',31,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Neptune_Voyager2_color_calibrated.png/800px-Neptune_Voyager2_color_calibrated.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Neptune','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('triton','Triton','moon','neptune','branch',9,1,30.069,'AU','2,707 km','5.88 days','-235 °C','A captured world orbiting Neptune backwards, with nitrogen geysers.','["Only large moon with a retrograde orbit", "Nitrogen geysers erupt 8 km high", "Almost certainly a captured Kuiper Belt object", "One of the coldest measured surfaces", "Has a thin nitrogen atmosphere", "Slowly spiralling into Neptune"]',32,'https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/Triton-usgs23-with-frame.jpg/800px-Triton-usgs23-with-frame.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Triton_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('nereid','Nereid','moon','neptune','branch',9,2,30.069,'AU','357 km','360 days','-235 °C','A small moon on one of the most eccentric orbits known.','["Its distance from Neptune varies sevenfold", "Discovered by Gerard Kuiper in 1949", "Third-largest moon of Neptune", "May be a captured object", "Orbit takes almost an Earth year", "Brightness varies unpredictably"]',33,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Nereid-Voyager2.jpg/800px-Nereid-Voyager2.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Nereid_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('kuiper_belt','Kuiper Belt','region',NULL,'main',10,0,39.0,'AU','~30–50 AU','~250 years','-220 °C','A vast doughnut of icy bodies beyond Neptune, home of the dwarf planets.','["Contains more than 100,000 objects over 100 km", "Source of most short-period comets", "Named after astronomer Gerard Kuiper", "New Horizons crossed it in the 2010s", "Holds Pluto, Makemake and Haumea", "Roughly 20 times wider than the asteroid belt"]',34,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Kuiper_belt_plot_objects_of_outer_solar_system.png/800px-Kuiper_belt_plot_objects_of_outer_solar_system.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Kuiper_belt','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('pluto','Pluto','dwarf_planet','kuiper_belt','branch',10,1,39.48,'AU','2,377 km','248 years','-229 °C','The best-known dwarf planet, a complex world of nitrogen ice and mountains.','["Sputnik Planitia is a vast nitrogen ice glacier", "Smaller than Earth''s Moon", "Its orbit sometimes brings it inside Neptune''s", "Has five known moons", "Reclassified as a dwarf planet in 2006", "New Horizons flew past in July 2015"]',35,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Pluto_in_True_Color_-_High-Res.png/800px-Pluto_in_True_Color_-_High-Res.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Pluto','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('charon','Charon','moon','pluto','branch',10,1,39.48,'AU','1,212 km','6.4 days','-220 °C','Pluto''s giant companion — the two form a true double system.','["Half the diameter of Pluto", "Both bodies orbit a point in open space", "Has a reddish polar region nicknamed Mordor", "Mutually tidally locked with Pluto", "Discovered in 1978", "Deep canyons stretch across its surface"]',36,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Charon_in_True_Color_-_High-Res.png/800px-Charon_in_True_Color_-_High-Res.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Charon_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('nix','Nix','moon','pluto','branch',10,2,39.48,'AU','~49 km','24.9 days','-230 °C','A small, oddly tumbling moon of Pluto.','["Rotation is chaotic and unpredictable", "Discovered by Hubble in 2005", "Highly reflective water-ice surface", "Shaped like an elongated jelly bean", "Named after the Greek goddess of night", "Likely formed from the Charon-forming impact"]',37,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Nix_best_view.jpg/800px-Nix_best_view.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Nix_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('hydra','Hydra','moon','pluto','branch',10,3,39.48,'AU','~51 km','38.2 days','-230 °C','Pluto''s outermost known moon, a bright chunk of water ice.','["Outermost of Pluto''s five moons", "Also tumbles chaotically", "Surface is nearly pure water ice", "Discovered alongside Nix in 2005", "Roughly 65 km at its longest axis", "Imaged by New Horizons in 2015"]',38,'https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Hydra_reprocessed.png/800px-Hydra_reprocessed.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Hydra_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('makemake','Makemake','dwarf_planet','kuiper_belt','branch',10,2,45.4,'AU','1,430 km','306 years','-239 °C','A bright, reddish dwarf planet in the classical Kuiper Belt.','["Second-brightest Kuiper Belt object after Pluto", "Named after a Rapa Nui creation deity", "Has one known dark moon, MK2", "Surface covered in methane and ethane ice", "Discovered in 2005", "Helped trigger Pluto''s reclassification"]',39,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Makemake_and_its_moon.jpg/800px-Makemake_and_its_moon.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Makemake','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('haumea','Haumea','dwarf_planet','kuiper_belt','branch',10,3,43.1,'AU','~1,560 × 996 km','284 years','-241 °C','A rapidly spinning, egg-shaped dwarf planet with its own ring.','["Rotates once every 3.9 hours", "Spun into an elongated ellipsoid", "First Kuiper Belt object found to have a ring", "Has two moons, Hi\u02bbiaka and Namaka", "Surface is crystalline water ice", "Has a collisional family of fragments"]',40,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Haumea_Hubble.png/800px-Haumea_Hubble.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Haumea','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('hiiaka','Hiʻiaka','moon','haumea','branch',10,1,43.1,'AU','~320 km','49 days','-241 °C','The larger outer moon of Haumea, coated in pure water ice.','["Largest of Haumea''s two moons", "Surface is almost pure crystalline water ice", "Discovered in 2005", "Named after a Hawaiian goddess", "Orbits Haumea in about 49 days", "Likely a collisional fragment of Haumea"]',41,'https://upload.wikimedia.org/wikipedia/en/thumb/9/9c/Hi%CA%BBiaka.png/800px-Hi%CA%BBiaka.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Hi''iaka_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('namaka','Namaka','moon','haumea','branch',10,2,43.1,'AU','~170 km','18 days','-241 °C','The smaller, inner moon of Haumea on a tilted orbit.','["Smaller and closer than Hi\u02bbiaka", "Orbit is strongly perturbed by Hi\u02bbiaka", "Discovered in 2005", "Named after a Hawaiian water spirit", "About a tenth of Hi\u02bbiaka''s mass", "Its orbital plane is notably inclined"]',42,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Namaka_Hubble.png/800px-Namaka_Hubble.png','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Namaka_(moon)','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('scattered_disk','Scattered Disk','region',NULL,'main',11,0,100.0,'AU','~30–100+ AU','1,000+ years','-243 °C','A sparse, tilted population of icy bodies flung outward by Neptune.','["Objects follow highly eccentric, inclined orbits", "Eris is its best-known member", "Source of most Jupiter-family comets", "Some members travel beyond 100 AU", "Shaped by gravitational scattering from Neptune", "Overlaps the outer Kuiper Belt"]',43,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Eris_and_dysnomia2.jpg/800px-Eris_and_dysnomia2.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Scattered_disc','Image courtesy of NASA/JPL/ESA via Wikimedia Commons'),
('oort_cloud','Oort Cloud','region',NULL,'main',12,0,2000.0,'AU','~2,000–100,000 AU','millions of years','-269 °C','The distant spherical shell of icy bodies that marks the Solar System''s true edge.','["Extends roughly 2,000 to 100,000 AU from the Sun", "Source of long-period comets", "May contain trillions of icy bodies", "Never directly observed \u2014 inferred from comet orbits", "Its outer edge is the Sun''s gravitational boundary", "Voyager 1 will need ~300 years to reach it"]',44,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/PIA17046_-_Voyager_1_Goes_Interstellar.jpg/800px-PIA17046_-_Voyager_1_Goes_Interstellar.jpg','Wikimedia Commons / NASA-ESA imagery','https://en.wikipedia.org/wiki/Oort_cloud','Image courtesy of NASA/JPL/ESA via Wikimedia Commons')
